void ExGeoPair::computeBallPlane(RBX::PairParams& _params)
{
	const G3D::Vector3& body0PV = this->body0->position.translation;
	const G3D::CoordinateFrame& body1PV = this->body1->position;
	const G3D::Vector3& myoffset1 = *this->offset1;
	const G3D::Matrix3& R = body1PV.rotation;
	const G3D::Vector3& T = body1PV.translation;
	G3D::Vector3 worldPoint(
		R[0][2]*myoffset1[2] + R[0][1]*myoffset1[1] + R[0][0]*myoffset1[0] + T[0],
		R[1][2]*myoffset1[2] + R[1][1]*myoffset1[1] + R[1][0]*myoffset1[0] + T[1],
		R[2][2]*myoffset1[2] + R[2][1]*myoffset1[1] + R[2][0]*myoffset1[0] + T[2]);

	const G3D::Vector3& normal = -Math::getWorldNormal(this->pairData.normalID1, body1PV);

	_params.normal = normal;

	const G3D::Vector3& temp = worldPoint - body0PV;
	G3D::Vector3 someMathThing = normal.dot(temp) * normal;
	_params.position = body0PV + someMathThing;
	_params.length = someMathThing.length() - this->pairData.radius0;
}

