    Ogre::Matrix4 world;
    worldMatrix(world);
    Ogre::Matrix4 local;
    local.makeTransform(center,Ogre::Vector3(1,v2.y-v0.y,v2.z-v0.z),Ogre::Quaternion(1,0,0,0));
    world = world.concatenate(local);
    drawMesh(adornQuadMesh,world,textureMaterial);
}

}

