#include <windows.h>
#include <map>
#include <boost/thread/mutex.hpp>
#include <boost/thread/once.hpp>

namespace RBX {
namespace ViewNew {

struct Object {
    virtual ~Object();
    virtual void release();
};

struct Link {
    Object* object;
    Link* next;
};

class atomic_count {
public:
    long operator--() { return InterlockedDecrement(&value_); }
    operator long() const { return static_cast<long const volatile&>(value_); }
private:
    long value_;
};

struct Control {
    virtual ~Control();
    atomic_count refs;
    Link* links;
};

class ControlPtr {
public:
    Control* p;
    operator bool() const { return p != 0; }
    Control* operator->() const { return p; }
    __forceinline void reset()
    {
        if (p)
        {
            if (--p->refs == 0)
            {
                Link* link = p->links;
                while (link)
                {
                    link->object->release();
                    Link* tmp = link;
                    link = link->next;
                    delete tmp;
                }
                delete p;
            }
            p = 0;
        }
    }
};

struct Key {
    int data[6];
    bool operator<(const Key& other) const;
};

struct Entry {
    ControlPtr levels[4];
};

struct Cache {
    std::map<Key, Entry> map;
    boost::mutex mutex;
