    Link* next;
};

class atomic_count {
public:
    long operator--() { return InterlockedDecrement(&value_); }
private:
    long value_;
};

struct Control {
    virtual ~Control();
    atomic_count refs;
    Link* links;
};

class ControlPtr {
public:
    Control* p;
    ControlPtr() : p(0) {}
    __forceinline ~ControlPtr() { reset(); }
    __forceinline void reset()
    {
        if (p)
        {
            if (--p->refs == 0)
            {
                Link* link = p->links;
                while (link)
                {
                    link->object->release();
                    Link* tmp = link;
                    link = link->next;
                    delete tmp;
                }
                delete p;
            }
            p = 0;
        }
    }
};

