        Security::Context::current().requirePermission(Security::Administrator, fd->name.c_str());

    boost::shared_ptr<Reflection::DescribedBase> instance;

    if (!getPtr(L, 1, instance) || !instance)
        throw std::runtime_error(G3D::format(
