                lua_pushcclosure(L, ObjectBridge::callMemberFunction, 1);
                lua_pushlightuserdata(L, (void*)fd);
                lua_pushvalue(L, -2);
                lua_settable(L, LUA_ENVIRONINDEX);
            }

            RBXASSERT(lua_type(L, -1) == LUA_TFUNCTION);

            return 1;
        }
    }

    {
